const body = $input.first().json.body || {};
const headers = $input.first().json.headers || {};
const token = (body.token || '').trim();
if (!token || token.length < 12 || token.length > 64) {
  return [{ json: { _error: 'TOKEN_INVALID', _status: 400, _details: 'token requerido en body (12-64 chars)' }}];
}
const validDecisions = ['accepted','rejected','revision_requested'];
const decision = (body.decision || '').trim();
if (!validDecisions.includes(decision)) {
  return [{ json: { _error: 'DECISION_INVALID', _status: 400, _details: 'decision debe ser accepted | rejected | revision_requested' }}];
}
const signerName = (body.signer_name || '').trim();
if (decision === 'accepted' && !signerName) {
  return [{ json: { _error: 'SIGNER_REQUIRED', _status: 400, _details: 'signer_name requerido al aceptar (firma del cliente)' }}];
}
const signerEmail = (body.signer_email || '').trim() || null;
const comments = (body.comments || '').trim().slice(0, 2000) || null;
const ip = (headers['x-forwarded-for'] || headers['x-real-ip'] || '').toString().split(',')[0].trim() || null;
const userAgent = (headers['user-agent'] || '').toString().slice(0, 500) || null;
return [{ json: {
  token,
  decision,
  signer_name: signerName || null,
  signer_email: signerEmail,
  comments,
  ip_address: ip,
  user_agent: userAgent,
  request_id: 'req_' + Math.random().toString(36).slice(2, 10)
}}];

const rows = $input.all().map(i => i.json).filter(r => r && r.id);
const sess = $('Validate Body').first().json;
if (rows.length === 0) {
  return [{ json: { _error: 'PROPOSAL_NOT_FOUND', _status: 404, _details: 'Token desconocido', request_id: sess.request_id }}];
}
const p = rows[0];
const now = Date.now();
const exp = p.public_token_expires_at ? new Date(p.public_token_expires_at).getTime() : null;
if (exp && now > exp) {
  return [{ json: { _error: 'TOKEN_EXPIRED', _status: 410, _details: 'El enlace ha expirado', expired_at: p.public_token_expires_at, request_id: sess.request_id }}];
}
if (p.accepted_at) {
  return [{ json: { _error: 'ALREADY_DECIDED', _status: 409, _details: 'La propuesta ya tiene una decision registrada el ' + p.accepted_at, accepted_at: p.accepted_at, accepted_via: 'public_link', request_id: sess.request_id }}];
}
return [{ json: {
  proposal_id: p.id,
  project_id: p.project_id,
  tenant_id: p.tenant_id,
  current_status: p.status,
  decision: sess.decision,
  signer_name: sess.signer_name,
  signer_email: sess.signer_email,
  comments: sess.comments,
  ip_address: sess.ip_address,
  user_agent: sess.user_agent,
  request_id: sess.request_id
}}];
